INSERT INTO questions (id,quiz_id,question,options,answer,explanation,sort) VALUES ('nism-8-z0-q400','nism-8-z0','A trader buys one lot (25) of a call option, strike ₹1130, premium ₹30. At expiry the underlying settles at ₹1126. The net profit/(loss) is:','["-₹100","₹850","-₹1,500","-₹750"]',3,'Payoff = max(S − K, 0) − premium, times lot.',400) ON CONFLICT(id) DO UPDATE SET quiz_id=excluded.quiz_id,question=excluded.question,options=excluded.options,answer=excluded.answer,explanation=excluded.explanation,sort=excluded.sort WHERE questions.quiz_id IS NOT excluded.quiz_id OR questions.question IS NOT excluded.question OR questions.options IS NOT excluded.options OR questions.answer IS NOT excluded.answer OR questions.explanation IS NOT excluded.explanation OR questions.sort IS NOT excluded.sort;
INSERT INTO questions (id,quiz_id,question,options,answer,explanation,sort) VALUES ('nism-8-z0-q401','nism-8-z0','A long futures position (1 lot of 25) was entered at ₹2840. The daily settlement price is ₹2796. The MTM profit/(loss) credited is:','["-₹1,100","₹1,100","-₹44","₹0"]',0,'(2796 − 2840) × 25.',401) ON CONFLICT(id) DO UPDATE SET quiz_id=excluded.quiz_id,question=excluded.question,options=excluded.options,answer=excluded.answer,explanation=excluded.explanation,sort=excluded.sort WHERE questions.quiz_id IS NOT excluded.quiz_id OR questions.question IS NOT excluded.question OR questions.options IS NOT excluded.options OR questions.answer IS NOT excluded.answer OR questions.explanation IS NOT excluded.explanation OR questions.sort IS NOT excluded.sort;
INSERT INTO questions (id,quiz_id,question,options,answer,explanation,sort) VALUES ('nism-8-z0-q402','nism-8-z0','Spot price is ₹3900, financing rate 6% p.a., expected dividend ₹15 during the period, and futures expiry in 180 days. The fair futures price is:','["₹3,915.00","₹4,119.00","₹4,000.40","₹4,015.40"]',2,'F = S[1 + r·t/365] − D = ₹4,000.40.',402) ON CONFLICT(id) DO UPDATE SET quiz_id=excluded.quiz_id,question=excluded.question,options=excluded.options,answer=excluded.answer,explanation=excluded.explanation,sort=excluded.sort WHERE questions.quiz_id IS NOT excluded.quiz_id OR questions.question IS NOT excluded.question OR questions.options IS NOT excluded.options OR questions.answer IS NOT excluded.answer OR questions.explanation IS NOT excluded.explanation OR questions.sort IS NOT excluded.sort;
