- Theta: Time decay (accelerates rapidly in the final 10 days to expiry)
- Vega: Volatility sensitivity (highest for ATM options)',32,1,3) ON CONFLICT(id) DO UPDATE SET course_id=excluded.course_id,module_id=excluded.module_id,title=excluded.title,kind=excluded.kind,body=excluded.body,minutes=excluded.minutes,published=excluded.published,sort=excluded.sort WHERE lessons.course_id IS NOT excluded.course_id OR lessons.module_id IS NOT excluded.module_id OR lessons.title IS NOT excluded.title OR lessons.kind IS NOT excluded.kind OR lessons.body IS NOT excluded.body OR lessons.minutes IS NOT excluded.minutes OR lessons.published IS NOT excluded.published OR lessons.sort IS NOT excluded.sort;
